def load() -> pd.DataFrame:
    import geopandas as gpd
    import pandas as pd
    gdf = gpd.read_file('data/wildfire/input/nifc_geographic_areas.gpkg')
    if gdf.crs is None:
        gdf = gdf.set_crs('EPSG:4326')
    gdf = gdf[['GACCName', 'GACCAbbreviation', 'geometry']].dropna(subset=['GACCAbbreviation', 'geometry']).copy()
    gdf = gdf.to_crs('EPSG:5070')

    # Fix invalid geometries
    try:
        gdf['geometry'] = gdf.geometry.make_valid()
    except Exception:
        gdf['geometry'] = gdf.geometry.buffer(0)

    # Convert geometry to WKT to match expected table (non-binary) output type
    out = pd.DataFrame({
        'GACCName': gdf['GACCName'].astype(str),
        'GACCAbbreviation': gdf['GACCAbbreviation'].astype(str),
        'geometry_wkt': gdf.geometry.to_wkt()
    })
    return out
